import java.util.*;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class Main {
    public static void main(String[] args) {
        JalankanTest.kelas(LanggananTest.class);
    }
}

@ExtendWith(MockitoExtension.class)
class LanggananTest {
    @Mock
    Pembayaran bayar;

    @Mock
    Notifikasi notif;

    @InjectMocks
    Langganan langganan;

    @Test
    void bayarBerhasil() {
        when(bayar.tagih("sari", 50000)).thenReturn(true);
        assertTrue(langganan.aktifkan("sari"));
        verify(notif).kirim("sari", "Langganan aktif");
    }

    @Test
    void bayarGagal() {
        when(bayar.tagih("budi", 50000)).thenReturn(false);
        when(notif.terkirim()).thenReturn(0);
        assertFalse(langganan.aktifkan("budi"));
    }
}

interface Pembayaran {
    boolean tagih(String pengguna, int jumlah);
}

interface Notifikasi {
    void kirim(String pengguna, String pesan);

    int terkirim();
}

class Langganan {
    private final Pembayaran bayar;
    private final Notifikasi notif;

    Langganan(Pembayaran bayar, Notifikasi notif) {
        this.bayar = bayar;
        this.notif = notif;
    }

    boolean aktifkan(String pengguna) {
        if (!bayar.tagih(pengguna, 50000)) {
            return false;
        }
        notif.kirim(pengguna, "Langganan aktif");
        return true;
    }
}

