        return repo.simpan(judul.trim());
    }

    void selesaikan(int id) {
        Todo t = repo.cari(id);
        if (t == null) {
            throw new TodoTidakDitemukanException(id);
        }
        t.selesaikan();
        repo.perbarui(t);
    }

    void hapus(int id) {
        if (!repo.hapus(id)) {
            throw new TodoTidakDitemukanException(id);
        }
    }

    List<Todo> semua() {
        return repo.semua();
    }
}

